WITH with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT id, order_id, method, paid_at, status, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 6 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, APPROX_PERCENTILE(island_id, 0.9) AS island_id_p90, MIN(paid_at) AS first_seen, ROUND(AVG(island_id), 2) AS avg_island_id FROM sessionized GROUP BY CASE WHEN island_id >= 6 THEN 'LARGE' ELSE 'SMALL' END ORDER BY island_id_p90 ASC;
